export function EventFormPage({ edit = false }: { edit?: boolean }) {
  const { id = '' } = useParams<{ id: string }>();
  const detail = useGetEvent(id, { query: { enabled: edit && !!id, queryKey: ['/api/events', id] } });
  const venuesQuery = useListVenues();
  const create = useCreateEvent();
  const update = useUpdateEvent();
  const [, setLocation] = useLocation();
  const source = detail.data;
  const [form, setForm] = useState({ title: '', category: EventInputCategory.MOVIE as EventInputCategory, description: '', startsAt: '', venueId: '', premiumPrice: '24', standardPrice: '16', imageUrl: '' });
  useEffect(() => { if (source) setForm({ title: source.title, category: source.category, description: source.description, startsAt: source.startsAt.slice(0, 16), venueId: source.venue.id, premiumPrice: '24', standardPrice: String(source.minPrice), imageUrl: source.imageUrl ?? '' }); }, [source]);
  const set = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); if (edit) update.mutate({ id, data: { title: form.title, description: form.description, startsAt: new Date(form.startsAt).toISOString(), premiumPrice: Number(form.premiumPrice), standardPrice: Number(form.standardPrice) } }, { onSuccess: () => setLocation(`/organiser/events/${id}`) }); else { const payload: EventInput = { title: form.title, category: form.category, description: form.description, startsAt: new Date(form.startsAt).toISOString(), venueId: form.venueId, premiumPrice: Number(form.premiumPrice), standardPrice: Number(form.standardPrice), ...(form.imageUrl ? { imageUrl: form.imageUrl } : {}) }; create.mutate({ data: payload }, { onSuccess: (created) => setLocation(`/organiser/events/${created.id}`) }); } };
  const pending = create.isPending || update.isPending;
  return <PageFrame eyebrow={edit ? 'Edit event' : 'Organiser studio'} title={edit ? 'Tune the details.' : 'Put something on.'} intro="Give your audience the useful details first. You can always refine the story later."><form onSubmit={submit} className="mx-auto max-w-3xl space-y-5 rounded-2xl border border-border bg-card p-6 sm:p-8">{edit && detail.isLoading ? <div className="skeleton h-96 rounded-xl" /> : <><div className="grid gap-5 sm:grid-cols-[1fr_180px]"><label className="field">Event title<input required value={form.title} onChange={(e) => set('title', e.target.value)} data-testid="input-event-title" placeholder="e.g. An Evening with..." /></label><label className="field">Format<select value={form.category} disabled={edit} onChange={(e) => set('category', e.target.value)} data-testid="select-event-category"><option value="MOVIE">Movie</option><option value="CONCERT">Concert</option></select></label></div><label className="field">Description<textarea required rows={5} value={form.description} onChange={(e) => set('description', e.target.value)} data-testid="input-event-description" placeholder="What should people know before they book?" /></label><div className="grid gap-5 sm:grid-cols-2"><label className="field">Start time<input required type="datetime-local" value={form.startsAt} onChange={(e) => set('startsAt', e.target.value)} data-testid="input-event-starts-at" /></label>{!edit && <label className="field">Venue<select required value={form.venueId} onChange={(e) => set('venueId', e.target.value)} data-testid="select-event-venue"><option value="">Choose a venue</option>{(venuesQuery.data ?? []).map((venue) => <option key={venue.id} value={venue.id}>{venue.name} · {venue.city}</option>)}</select></label>}</div><div className="grid gap-5 sm:grid-cols-2"><label className="field">Standard price<input required type="number" min="1" step=".01" value={form.standardPrice} onChange={(e) => set('standardPrice', e.target.value)} data-testid="input-standard-price" /></label><label className="field">Premium price<input required type="number" min="1" step=".01" value={form.premiumPrice} onChange={(e) => set('premiumPrice', e.target.value)} data-testid="input-premium-price" /></label></div>{!edit && <label className="field">Image URL <span className="font-normal text-muted-foreground">(optional)</span><input value={form.imageUrl} onChange={(e) => set('imageUrl', e.target.value)} data-testid="input-event-image-url" placeholder="https://..." /></label>}<div className="flex flex-col-reverse justify-between gap-3 border-t border-border pt-5 sm:flex-row sm:items-center"><Link href={edit ? `/organiser/events/${id}` : '/organiser/events'} data-testid="link-cancel-event-form" className="text-center text-sm font-bold text-muted-foreground hover:text-foreground">Cancel</Link><button disabled={pending} data-testid="button-submit-event" className="rounded-lg bg-primary px-5 py-3 text-sm font-extrabold text-primary-foreground disabled:opacity-50">{pending ? 'Saving…' : edit ? 'Save changes' : 'Create event'}</button></div>{(create.isError || update.isError) && <ErrorNotice error={create.error ?? update.error} />}</>}</form></PageFrame>;
}

